<section id="hero" class="relative min-h-screen flex items-center justify-center overflow-hidden">
  
  <!-- Container Background Dual-Layer Crossfade -->
  <div class="absolute inset-0 z-0">
    <!-- Layer A (Default Visible) -->
    <img 
      id="hero-bg-layer-a" 
      src="{{ asset('images/background/bg-serumpun.png') }}" 
      alt="Khazanah Peradaban Serumpun A" 
      class="hero-bg-slide opacity-100"
    >
    <!-- Layer B (Default Hidden) -->
    <img 
      id="hero-bg-layer-b" 
      src="{{ asset('images/background/bg-serumpun.png') }}" 
      alt="Khazanah Peradaban Serumpun B" 
      class="hero-bg-slide opacity-0"
    >
    
    <!-- Dark Gradient Masking -->
    <div class="absolute inset-0 bg-gradient-to-b from-black/85 via-black/45 via-55% to-[#12161c] pointer-events-none"></div>
    <div class="absolute inset-0 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-transparent via-black/30 to-black/80 pointer-events-none"></div>
  </div>

  <!-- Hero Content Center-Aligned -->
  <div class="relative z-10 max-w-4xl mx-auto px-4 sm:px-6 text-center text-white pt-24 pb-16 flex flex-col items-center">
    
